"""lotus: tpch/Q17; common numeric v4; explicitly rewritten workload.
Source: original/tpch/plop/Q17.sql
Run via experiments.validation.faithful_runtime; model settings are external.
"""
SYSTEM = 'lotus'
QUERY_ID = 'tpch/Q17'
SOURCE = 'original/tpch/plop/Q17.sql'

RELATIONAL_SQL = "WITH customer_sample AS MATERIALIZED (\n  SELECT\n    *\n  FROM customer\n  ORDER BY\n    c_custkey ASC\n  LIMIT 120\n)\nSELECT\n  *\nFROM (\n  SELECT\n    of.o_orderkey,\n    of.o_custkey,\n    of.o_orderdate,\n    of.o_orderpriority,\n    of.o_totalprice,\n    lf.l_partkey,\n    lf.l_suppkey,\n    lf.l_shipmode,\n    lf.l_shipinstruct,\n    lf.l_quantity,\n    lf.l_extendedprice,\n    lf.l_discount,\n    lf.l_tax,\n    lf.l_returnflag,\n    ps.p_name,\n    ps.p_type,\n    ps.p_brand,\n    ps.s_name,\n    ps.supplier_nation\n  FROM (\n    SELECT\n      o.o_orderkey,\n      o.o_custkey,\n      o.o_orderdate,\n      o.o_orderpriority,\n      o.o_totalprice,\n      o.o_comment\n    FROM orders AS o\n    WHERE\n      o.o_orderdate >= CAST('1993-01-01' AS DATE)\n      AND o.o_orderdate < CAST('1997-01-01' AS DATE)\n      AND o.o_orderstatus IN ('O', 'F')\n      AND o.o_totalprice > 50000\n      AND SEMANTIC_FILTER(\n        'You are triaging enterprise orders for operations monitoring. From the priority label, total price, and order comment, does this order look important enough to deserve active follow-up by an operations manager?\nOrder Priority: {0}\nTotal Price: {1}\nComment: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n        CAST(o.o_orderpriority AS TEXT),\n        CAST(o.o_totalprice AS TEXT),\n        CAST(o.o_comment AS TEXT)\n      )\n  ) AS of\n  JOIN (\n    SELECT\n      l.l_orderkey,\n      l.l_partkey,\n      l.l_suppkey,\n      l.l_shipmode,\n      l.l_shipinstruct,\n      l.l_quantity,\n      l.l_extendedprice,\n      l.l_discount,\n      l.l_tax,\n      l.l_returnflag\n    FROM lineitem AS l\n    WHERE\n      l.l_shipdate >= CAST('1993-01-01' AS DATE)\n      AND l.l_shipdate < CAST('1998-01-01' AS DATE)\n      AND l.l_quantity BETWEEN 5 AND 40\n      AND l.l_discount BETWEEN 0.01 AND 0.10\n      AND l.l_shipmode IN ('AIR', 'REG AIR', 'TRUCK')\n  ) AS lf\n    ON lf.l_orderkey = of.o_orderkey\n  JOIN (\n    SELECT\n      p.p_partkey,\n      p.p_name,\n      p.p_type,\n      p.p_brand,\n      s.s_suppkey,\n      s.s_name,\n      n.n_name AS supplier_nation\n    FROM part AS p\n    JOIN partsupp AS ps\n      ON ps.ps_partkey = p.p_partkey\n    JOIN supplier AS s\n      ON s.s_suppkey = ps.ps_suppkey\n    JOIN nation AS n\n      ON n.n_nationkey = s.s_nationkey\n    WHERE\n      p.p_size BETWEEN 5 AND 35 AND ps.ps_supplycost BETWEEN 10 AND 1000\n  ) AS ps\n    ON ps.p_partkey = lf.l_partkey AND ps.s_suppkey = lf.l_suppkey\n) AS j\nJOIN (\n  SELECT\n    *\n  FROM customer_sample AS c\n  WHERE\n    SEMANTIC_FILTER(\n      'You are identifying high-value B2B customer profiles. From the customer name format, market segment, balance, and account comment, does this record look like a customer worth prioritizing in business account analytics?\nCustomer Name: {0}\nMarket Segment: {1}\nAccount Balance: {2}\nComment: {3}\nReturn a single YES or NO, with no other words. If uncertain, return NO.',\n      CAST(c.c_name AS TEXT),\n      CAST(c.c_mktsegment AS TEXT),\n      CAST(c.c_acctbal AS TEXT),\n      CAST(c.c_comment AS TEXT)\n    )\n) AS c\n  ON j.o_custkey = c.c_custkey\n  AND SEMANTIC_FILTER(\n    'You are an operations manager assessing whether a high-value customer is associated with an important order that requires active follow-up. The customer has the following profile:\nCustomer Name: {0}\nMarket Segment: {1}\nAccount Balance: {2}\nComment: {3})',\n    CAST(c.c_name AS TEXT),\n    CAST(c.c_mktsegment AS TEXT),\n    CAST(c.c_acctbal AS TEXT),\n    CAST(c.c_comment AS TEXT)\n  );\n"

def run(tables, job, model=None):
    from experiments.validation.faithful_runtime import run_lotus_relational
    return run_lotus_relational(RELATIONAL_SQL, tables, job, model=model)

if __name__ == '__main__':
    from experiments.validation.faithful_runtime import query_main
    query_main(globals())
